package edu.gatech.chai.MDI.model.resource.util;

import org.hl7.fhir.r4.model.CodeableConcept;
import org.hl7.fhir.r4.model.Coding;

public class DocumentReferenceMDIReportUtil {
	// Appropriate type and category for MDI Report.  This is a clinical note that is generated by the MDI system.
	// Set default type to UNK since this depends on the type of report being generated.  
	// The category is set to clinical note since this is a clinical note generated by the MDI system.
	public static final CodeableConcept type = CommonUtil.unknownCode;
	public static final CodeableConcept category = new CodeableConcept().addCoding(
			new Coding(CommonUtil.usCoreDocumentreferenceCategory,"clinical-note","Clinical Note"));
}
